head.script:
/* ★Wcraft guide★    
스크립트 수작업 유의사항
*/


//★Wcraft guide★ include부분 주석처리 -> include("../js/libRoundPanel.js");
//★Wcraft guide★ include부분 주석처리 -> include("../js/utils.js");
//★Wcraft guide★ include부분 주석처리 -> include("../js/session.js");
//★Wcraft guide★ include부분 주석처리 -> include("../js/PopupCalendar.js");
//★Wcraft guide★ include부분 주석처리 -> include("../js/stf.js");
//★Wcraft guide★ include부분 주석처리 -> include("../js/bns_common.js");
//★Wcraft guide★ include부분 주석처리 -> include("../js/list_common.js");
scwin.vScrenID = 'ULDBNS90018.xml';
scwin.vMktactCd = '202'; //채권시장조치구분코드	
scwin.pBndApplId = '';
scwin.vBndListProcsTpCd = 1; //채권처리구분(1:신청,2:접수)
scwin.vDtlInfoRowCount = 0;
scwin.arrPar = new Array();
scwin.fn_GetPar, scwin.fn_SetPar;
scwin.vViewYN = 'Y';
scwin.pIsurCd = '';
scwin.onpageload = function() {
    scwin.gform_onload();
};
scwin.onpageunload = function() {
};

/********************************************** 
 * 함수명   : fn_SetParam
 * 설명       : 부모창에서 받은 데이터를 설정한다.
 ***********************************************/
scwin.fn_SetParam = function() {
    var prt = $c.frame.path("../");
    if (prt != undefined) {
        scwin.fn_GetPar = prt.scwin.fn_GetPar;
        scwin.fn_SetPar = prt.scwin.fn_SetPar;
    }
    if (scwin.fn_GetPar != undefined) {
        scwin.fn_GetPar(scwin.arrPar);
        scwin.pBndApplId = scwin.arrPar[0].BND_APPL_ID;
        scwin.pIsurCd = scwin.arrPar[0].ISUR_CD;
    }
};



/********************************************** 
 * 함수명  	 : fn_dtl_sync
 * 설명       : 상세조회
 ***********************************************/
scwin.fn_dtl_sync = function() {
    var dsNm = 'BNS_CHG_BND_INFO';
    var qryId = 'lds.stf.bnschg.select.readChgBndInfo_202';
    var param = '&{P}V_BND_LIST_PROCS_TP_CD=' + scwin.vBndListProcsTpCd;
    param += '&{P}V_MKTACT_CD=' + scwin.vMktactCd;
    param += '&{P}V_BND_APPL_ID=' + scwin.pBndApplId;
    param += '&{P}V_VIEW_YN=' + scwin.vViewYN;
    $c.bns.fn_SearchBns(scwin.vScrenID, dts_DtlInfo, dsNm, qryId, param);
};


/********************************************** 
 * 함수명  	 : fn_chgBndList
 * 설명       : 합병/회사분할 회차 종목 조회
 ***********************************************/
scwin.fn_chgBndList = function() {
    var dsNm = 'BNS_CHG_BND_LIST';
    var qryId = 'lds.stf.bnschg.select.readChgBndIsuInfo_202';
    var param = '&{P}V_BND_LIST_PROCS_TP_CD=' + scwin.vBndListProcsTpCd;
    param += '&{P}V_BND_APPL_ID=' + scwin.pBndApplId;
    param += '&{P}V_VIEW_YN=' + scwin.vViewYN;
    dts_IsuList.SyncLoad = true;
    $c.bns.fn_SearchBns(scwin.vScrenID, dts_IsuList, dsNm, qryId, param);
};


/********************************************** 
 * 설명 : 채권신고담당자 조회
 ***********************************************/
scwin.fn_Search2 = function() {
    dts_List3.removeAll();
    var dsNm = 'BNS_BND_DECL_CHRG_LIST';
    var qryId = 'lds.stf.bnsdecl_mgr.select.selectBndDeclChrgList';
    var param = '&{P}V_ISUR_CD=' + scwin.pIsurCd;
    $c.bns.fn_SearchBns(scwin.vScrenID, dts_List3, dsNm, qryId, param);
};


/********************************************** 
 * 함수명  	 : fn_IsuCdCombo
 * 설명       : 종목기준명 콤보 데이터 조회
 ***********************************************/
scwin.fn_IsuCdCombo = function() {
    var param = "&{P}V_ISUR_CD=" + dts_DtlInfo.getCellData(1, "ISUR_CD");
    var dsNm = 'BNS_ISU_CD';
    var qryId = 'lds.stf.bnschg.select.listIsuBasNm';
    $c.bns.fn_SearchBns(scwin.vScrenID, dts_IsuSelList, dsNm, qryId, param);
};


/********************************************** 
 * 함수명   : fn_SetComboCode
 * 설명       : 콤보데이터 정의 (채권유형코드)
 ***********************************************/
scwin.fn_SetComboCode = function() {
    var dsNm = 'BNS_COM_CD';
    var qryId = 'lds.stf.bnscommon.select.selectBndClss';
    var param = '';
    $c.bns.fn_SearchBns(scwin.vScrenID, dts_BndClassCd, dsNm, qryId, param);
    $c.bns.fn_SetBnsCombo(scwin.vScrenID, dts_BndTpCd, '01422');
};


/********************************************** 
 * 함수명   : fn_GetCommonKey
 * 설명       : 팝업에 넘길 키데이터를 정의한다.
 ***********************************************/
scwin.fn_GetCommonKey = function(arrPar) {
    scwin.arrPar[0] = {
        //첨부문서 목록 팝업	
        BND_APPL_ID: dts_DtlInfo.getCellData(1, "BND_APPL_ID"),
        BND_LIST_PROCS_TP_CD: dts_DtlInfo.getCellData(1, "BND_LIST_PROCS_TP_CD"),
        ISU_CD: dts_DtlInfo.getCellData(1, "ISU_CD")
    };
    return
    // ********************************************************************
    // [WebSquare 전환 추가] 원본 소스와 비교 필요
    // 
    // ********************************************************************
    scwin.arrPar, length;
};


/********************************************** 
 * 함수명   : fn_GetBasNm
 * 설명       : 채권기준명 팝업에 넘길 키데이터를 정의한다.
 ***********************************************/
scwin.fn_GetBasNm = function(arrPar) {
    scwin.arrPar[0] = {
        ISUR_CD: dts_DtlInfo.getCellData(1, "ISUR_CD"),
        MKTACT_TP_CD: scwin.vMktactCd
    };
    return
    // ********************************************************************
    // [WebSquare 전환 추가] 원본 소스와 비교 필요
    // 
    // ********************************************************************
    scwin.arrPar, length;
};

/********************************************** 
 * 함수명   : fn_SetBasNm
 * 설명       : 채권기준명 팝업에서 받은 데이터를 설정한다.
 ***********************************************/
scwin.fn_SetBasNm = function(arrPar) {
    if ("Y" == scwin.arrPar[0].SUCCESS_YN) {
        dts_IsuSelList.Reset();
    }
};
scwin.gform_onload = function() {
    $c.bns.BnsPanelToGroupBox(pnl_Req); //패널라운드처리(신청)
    $c.bns.BnsPanelToGroupBox(pnl_DtlInfo); //패널라운드처리(상세)
    $c.bns.BnsPanelToGroupBox(pnl_Acpt); //패널라운드처리(접수)	

    tab_List.setSelectedTabIndex(1);

    //콤보데이터 설정
    scwin.fn_SetComboCode();
    scwin.fn_SetParam(); //호출파라미터설정	
    scwin.fn_dtl_sync(); //상세조회

    // 채권신고담당자 조회
    scwin.fn_Search2();
};
scwin.tab_List_OnSelChanged = function(nIndex) {
    scwin.vBndListProcsTpCd = nIndex;
    scwin.fn_dtl_sync(); //상세조회

    // 채권신고담당자 조회
    scwin.fn_Search2();
};
scwin.dts_DtlInfo_OnLoadCompleted = function(rowcount) {
    scwin.vDtlInfoRowCount = rowcount;
    scwin.fn_chgBndList(); //종목명 회차 조회
    scwin.fn_IsuCdCombo(); //종목기준명 콤보데이터 설정

};
scwin.img_StrtDd_onclick = function() {
    if (scwin.vDtlInfoRowCount == 0) return;
    popUpCalendar2(edt_StrtDd);
};
scwin.btn_Attach_onclick = function() {
    if (scwin.vDtlInfoRowCount == 0) return;
    if ("N" == dts_DtlInfo.getCellData(1, "HAS_ATTACH_DOC")) {
        $c.win.alert("연결된 팩스/첨부문서가 없습니다.");
        return;
    }
    scwin.fn_GetPar = fn_GetCommonKey;
    $c.bns.fn_PopAttachDocSearch(lbl_BndApplId);
};
scwin.cmb_BndClssCd_OnSelChange = function() {
    /** 채권분류 적용 */
    for (var i = 1; i <= dts_IsuList.getTotalRow(); i++) {
        dts_IsuList.setCellData(i, "AFCHG_BND_CLASS_CD", $c.stf.getObjectValue(cmb_BndClssCd));
    }
};
scwin.cmb_BndTpCd_OnSelChange = function() {
    /** 채권유형 적용 */
    for (var i = 1; i <= dts_IsuList.getTotalRow(); i++) {
        dts_IsuList.setCellData(i, "AFCHG_BND_TP_CD", $c.stf.getObjectValue(cmb_BndTpCd));
    }
};
scwin.cmb_IsuNm_OnSelChange = function() {
    /** 종목기준명 적용 */
    var vIdx = cmb_IsuNm.getSelectedIndex() + 1;
    for (var i = 1; i <= dts_IsuList.getTotalRow(); i++) {
        dts_IsuList.setCellData(i, "AFCHG_ISU_NM", dts_IsuSelList.getCellData(vIdx, "TEXT"));
        dts_IsuList.setCellData(i, "AFCHG_ISU_ABBRV", dts_IsuSelList.getCellData(vIdx, "TEXT2"));
        dts_IsuList.setCellData(i, "AFCHG_ISU_ENG_NM", dts_IsuSelList.getCellData(vIdx, "TEXT3"));
        dts_IsuList.setCellData(i, "AFCHG_ISU_ENG_ABBRV", dts_IsuSelList.getCellData(vIdx, "TEXT4"));
    }
};
scwin.btn_Close_onclick = async function() {
    await $c.frame.CloseFrame();
};
scwin.dts_BndTpCd_OnLoadCompleted = function(rowcount) {
    //채권유형 공백란 추가
    dts_BndTpCd.insertRow(dts_BndTpCd.getRowPosition() - 1);
};
scwin.dts_IsuSelList_OnLoadCompleted = function(rowcount) {
    if (scwin.vBndListProcsTpCd == 2) {
        var vCmbRow = $c.cp.getNameValueRow(dts_IsuSelList, "TEXT", dts_IsuList.getCellData(1, "AFCHG_ISU_NM"));
        cmb_IsuNm.setSelectedIndex(vCmbRow - 1);
    }
};
